import { describe, expect, it } from "vitest";

import { createRetrySchedule } from "./retry-schedule.js";
import { DEFAULT_RETRY_POLICY } from "./retry-policy.js";

describe("request-local retry schedule state", () => {
	it("creates independent schedules for sequential requests", () => {
		const first = createRetrySchedule(3, DEFAULT_RETRY_POLICY);
		const second = createRetrySchedule(3, DEFAULT_RETRY_POLICY);
		expect(first).not.toBe(second);
	});

	it("does not share state between concurrent schedules", () => {
		const a = createRetrySchedule(2, DEFAULT_RETRY_POLICY);
		const b = createRetrySchedule(2, DEFAULT_RETRY_POLICY);
		expect(a).not.toBe(b);
	});
});

