import { describe, expect, it } from "vitest";

import {
	createConfig,
	fetch,
	mergeConfig,
} from "./fetch.js";

describe("fetch client configuration", () => {
	it("exposes the ambient request config for overrides", () => {
		const config = createConfig();
		expect(config.baseURL).toBeUndefined();
	});

	it("merges later configs over earlier ones without mutation", () => {
		const base = createConfig({ baseURL: "https://hevy.app" });
		const next = mergeConfig(base, { headers: { "x-trace": "t1" } });
		expect(next.baseURL).toBe("https://hevy.app");
		expect(base.headers).toBeUndefined();
	});
});

